CAST(ORDER_DATE AS DATE) AS Order_Date ,CAST(ORDER_DATE AS datetime) ORDER_TIME ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) AS gross_sales_before_tax ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,NULL AS MRP ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_ORDER_STATUS ,UPPER(b.shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,saleOrderItemCode AS SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS payment_gateway ,payment_mode ,COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivered_date AS delivered_date ,CASE WHEN UPPER(FINAL_SHIPPING_STATUS) IN (\'DELIVERED\') THEN 1 END AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,CASE WHEN return_flag = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN return_flag = 1 THEN CAST(selling_price AS FLOAT64) END AS returned_sales ,CASE WHEN return_flag = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,CASE WHEN order_status = \'COMPLETE\' THEN date_diff(CAST(delivered_date AS DATE), CAST(order_date AS DATE),day) ELSE date_diff(CURRENT_DATE(), CAST(order_date AS DATE),day) END AS days_in_shipment ,NULL AS ACQUISITION_DATE ,sku_code ,UPPER(b.product_name_final) AS PRODUCT_NAME_FINAL ,UPPER(coalesce(b.Product_Category,cm.final_category)) AS PRODUCT_CATEGORY ,UPPER(b.product_sub_category) AS PRODUCT_SUB_CATEGORY ,b.commonsku ,UPPER(warehouse_name) AS warehouse ,b.pincode ,fa.pincode source_pincode ,null discount_codes ,null as style_id ,null as lot FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_unicommerce_fact_items b left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from thd-pharma-wh.MAPLEMONK.facility_pincode ) where rw = 1 ) fa on lower(b.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM thd-pharma-wh.MAPLEMONK.shipment_status_mapping ) ShipMap WHERE ShipMap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) LEFT JOIN thd-pharma-wh.MAPLEMONK.category_mapping cm on upper(cm.category) = upper(b.product_category) WHERE NOT (LOWER(b.marketplace) LIKE ANY (\'%shopify%\') or LOWER(b.marketplace) LIKE ANY (\'%amazon%\', \'%flipkart%\')) ; CREATE OR REPLACE TABLE thd-pharma-wh.MAPLEMONK.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case WHEN upper(m.final_shipping_status) LIKE \'%RTO%\' OR upper(m.final_shipping_status) LIKE \'%FAILURE%\' OR upper(m.order_status) LIKE \'%UNFULFILLABLE%\' OR upper(m.order_status) LIKE \'%RETURNED TO SELLER%\' OR upper(m.order_status) LIKE \'%RETURNING TO SELLER%\' OR upper(m.order_status) LIKE \'%UNDELIVERED%\' OR (upper(m.order_status) LIKE \'%CANCEL%\' AND upper(m.final_shipping_status) = \'IN TRANSIT\') THEN 1 ELSE 0 end as RTO_flag, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then 1 else 0 end as DTO_flag, case when upper(m.final_shipping_status) like \'%RTO%\' or upper(m.final_shipping_status) like \'%FAILURE%\' or upper(m.order_status) like \'%UNFULFILLABLE%\' or upper(m.order_status) like \'%RETURNED TO SELLER%\' or upper(m.order_status) like \'%RETURNING TO SELLER%\' or upper(m.order_status) like \'%UNDELIVERED%\' or (upper(m.order_status) like \'%CANCEL%\' and upper(m.final_shipping_status) = \'IN TRANSIT\') then m.selling_price ELSE 0 end as RTO_value, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then m.selling_price else 0 end as DTO_value, Case when upper(m.product_category) like any (\'EYES\',\'KAJAL\', \'EYELINER\', \'LASH MASCARA\') then \'EYES\' when upper(m.product_category) like any (\'KIT\', \'FACIAL KIT\') then \'KIT\' when upper(m.product_category) like any (\'BODY OILS\', \'PAIN RELIEF\') then \'BODY\' when upper(m.product_category) like any (\'BLUSH\', \'FOUNDATION\', \'FACE WASH AND SCRUB\', \'FACE\', \'DEWY FOUNDATION\') then \'FACE\' when upper(m.product_category) like any (\'PIGMENTATION LIPSTICK\', \'LIP\', \'LIPS\') then \'LIPS\' when upper(m.product_category) like any (\'WOMENS PERSONAL CARE\') then \'WOMENS PERSONAL CARE\' when upper(m.product_category) like any (\'HAIR\', \'HAIR OILS\') then \'HAIR\' else upper(m.product_category) end as Final_Category, (cast(co.COGS as float64) * m.quantity) as COGS_Value, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM thd-pharma-wh.MAPLEMONK.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM thd-pharma-wh.MAPLEMONK.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN thd-pharma-wh.MAPLEMONK.marketplace_mapping mm ON lower(m.marketplace) = lower(mm.marketplace) LEFT JOIN( Select * FROM maplemonk.thd_pharma_gs_SKU_MRP_COGS ) co ON upper(co.sku_code) = upper(m.commonsku) ; ALTER TABLE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, channel, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; UPDATE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'AP\', \'ANDHARA PRADESH\', \'ANDHRA PRADESH\', \'ANDHRA&#32;PRADESH\', \'ANDHRAPRADESH\', \'ANDRA PRADESH\', \'ANDRAPRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CH\',\'CHANDIGARH\', \'CHANDIGARH UT\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\', \'CHATTISGARH\', \'CHHATISGARH\', \'CHHATTISGARH\', \'CHHATTISHGARH\') THEN \'CHATTISGARH\' WHEN UPPER(state) IN (\'DADRA & NAGAR HAVELI & DAMAN & DIU\', \'DADRA & NAGAR HAVELI AND DAMAN & DIU\', \'DADRA AND NAGAR HAVELI\', \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\', \'DAMAN & DIU\', \'DAMAN AND DIU\', \'DADRA & NAGAR HAVELI\', \'DD\') THEN \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\' WHEN UPPER(state) IN (\'DELH\', \'DELHI\', \'DELHI NCR\', \'DELHI, HINDU\', \'DELHI, INDIA\', \'DELHI-110032\', \'NEW DEHLI\', \'NEW DELHI\', \'NEW DELHI,INDIA\', \'NORTH DELHI\', \'ROHINI, NEW DELHI\', \'SOUTH DELHI\', \'DL\') THEN \'DELHI\' WHEN UPPER(state) IN (\'GOA\', \'GA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GUJARAT\', \'GUJARÄT\', \'GUJRAT\', \'GT\', \'GJ\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HARIYANA\', \'HARYABA\', \'HARYANA\', \'HR\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'H.P.\', \'HIMACHAL PARDESH\', \'HIMACHAL PRADESH\', \'HP\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'J&K\', \'JAMMU AND KASHMIR\', \'JAMMU AND KASHMIR (UT)\', \'JAMMU N KASHMIR\', \'JAMMUANDKASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\', \'JHARKHAND\', \'JK\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\', \'KARANATAKA\', \'KARNAATAKA\', \'KARNATAKA\', \'KARNATAKA,\', \'KODAGU KARNATAKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\', \'KERAALA\', \'KERALA\', \'KERELA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'LADAKH\') THEN \'LADAKH\' WHEN UPPER(state) IN (\'LAKSHADWEEP\') THEN \'LAKSHWADEEP\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\', \'M P\', \'M. P.\', \'M.P\', \'M.P.\', \'MADHYA PARDESH\', \'MADHYA PRADEDH\', \'MADHYA PRADESH\', \'MADHYAPRADESH\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\', \'MAHAARASHRA\', \'MAHARAAHTRA\',\'MAHARAASHTRA\', \'MAHARARSHTRA\', \'MAHARASHTRA\', \'MAHARASHTRA ,PUNE\', \'MAHARASHTRA .\', \'MAHARASTR\', \'MAHARASTRA\', \'RAIGAD,MAHARASHTRA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\', \'MEGHALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\', \'NAGALAND\', \'NA\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\', \'ODISHA\', \'OR;ORISSA\', \'ORISSA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PONDICHERRY\', \'PUDUCHERRY\', \'PUNCHERRY\') THEN \'PONDICHERRY\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\', \'PANJAB\', \'PUNAJB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\', \'JAIPUR\', \'RAJASTHAN\', \'RAJASTION\', \'RAJESTHAN\', \'RAJSHTHAN\', \'RAJSTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\', \'CHENNAI, TAMIL NADU\', \'TAMIL NADU\', \'TAMILNADU\', \'TAMILNADU,INDIA\', \'TAMILUNAADU\', \'TIRUVANNAMALAI DISTRICT, TAMILNADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\', \'HYDERABAD TELENGANA\', \'TALANGANA\', \'TELANAGANA\', \'TELANGA\', \'TELANGANA\', \'TELANGANA HYD\', \'TELANGANA STATE\', \'TELENAGANA\', \'TELENGANA\', \'TELENGANA STATE\', \'TG\') THEN \'TELANGANA\' WHEN UPPER(STATE) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\', \'RAMPUR UTTAR PRADESH\', \'U P\', \'U. P.\', \'U.P\', \'U.P.\', \'UTTAP PRADESH\', \'UTTAR PARDES\', \'UTTAR PARDESH\', \'UTTAR PRADESH\', \'UTTAR PRADESH (UP)\', \'UTTARPRADESH\', \'UTTER PARDESH\', \'UTTER PRADESH\', \'UTTRA PRADESH\', \'UTTTAR PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\',\'UTTARAKHAND\', \'UTTRAKAND\', \'UTTRAKHAND\', \'UTTARANCHAL\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\', \'INDIA,WEST BENGAL, KOLKATA\', \'KOLKATA , WEST BENGAL\', \'W. B\', \'WEAT BENGAL\', \'WEST BENGAL\', \'WESTBENGAL\') THEN \'WEST BENGAL\' END WHERE UPPER(state) IN ( \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\', \'AP\',