) AS REFERENCE_CODE, Source FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE; CREATE TABLE IF NOT EXISTS thd-pharma-wh.MAPLEMONK.thd_pharma_wh_unicommerce_returns_intermediate ( MARKETPLACE STRING, SOURCE STRING, ORDER_ID STRING, REFERENCE_CODE STRING, PHONE STRING, NAME STRING, EMAIL STRING, ORDER_DATE TIMESTAMP, RETURN_DISPLAYCODE STRING, RETURN_STATUS STRING, INVENTORY_RECEIVED_DATE TIMESTAMP, RETURN_COMPLETE_DATE TIMESTAMP, RETURN_INVOICE_DISPLAY_CODE STRING, RETURN_COURIER STRING, RETURN_PROVIDER_SHIPPING_STATUS STRING, RETURN_TRACKING_NUMBER STRING, RETURN_TYPE STRING, sale_order_item_code STRING, ITEMSKU STRING, ITEM_NAME STRING, INVENTORY_TYPE STRING ); CREATE OR REPLACE TABLE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_unicommerce_returns_fact_items AS SELECT IFNULL(FE.channel, \'NA\') AS Marketing_CHANNEL, FE.quantity AS RETURNED_QUANTITY, FE.selling_price AS TOTAL_RETURN_AMOUNT, FE.tax AS RETURN_TAX, FE.selling_price - FE.tax AS RETURN_AMOUNT_WITHOUT_TAX, FR.* FROM (select * from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_unicommerce_returns_intermediate where RETURN_DISPLAYCODE is not null) FR LEFT JOIN ( SELECT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, SALEORDERITEMCODE, channel, Source, SUM(quantity) AS quantity, SUM(selling_price) AS Selling_price, SUM(tax) AS tax FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_sales_consolidated GROUP BY REFERENCE_CODE, SALEORDERITEMCODE, channel, Source ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE AND FR.sale_order_item_code = FE.SALEORDERITEMCODE; CREATE OR REPLACE TABLE thd-pharma-wh.MAPLEMONK.thd_pharma_wh_returns_consolidated AS SELECT UPPER(er.MARKETPLACE) AS Marketplace, mm.FINAL_MARKETPLACE, coalesce(a.Brand, er.brand) as Brand, cast(er.RETURN_DATE as datetime) return_Date, Case when lower(er.marketplace) like \'%amazon%\' and lower(coalesce(a.Brand, er.brand)) like \'%ozone%\' then \'AMAZON OZONE\' when lower(er.marketplace) like \'%amazon%\' and lower(coalesce(a.Brand, er.brand)) like any (\'%db%\', \'%dream%\') then \'AMAZON DB\' else UPPER(er.Marketing_CHANNEL) end AS Marketing_channel, SUM(er.RETURNED_QUANTITY) AS TOTAL_RETURNED_QUANTITY, SUM(er.total_credit_note_amount) AS TOTAL_RETURN_AMOUNT, Null AS TOTAL_RETURN_TAX, Null AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_easyecom_returns_fact_items er left join(select * from maplemonk.thd_pharma_wh_AMAZON_DB_FACT_ITEMS qualify row_number() over (partition by order_id, sku order by order_timestamp) =1 ) a on a.order_id = er.reference_code and a.sku = er.sku LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from thd-pharma-wh.MAPLEMONK.marketplace_mapping ) where rw =1 ) mm ON lower(er.marketplace) = lower(mm.marketplace) GROUP BY er.Marketplace, mm.final_marketplace, RETURN_DATE, Marketing_channel, coalesce(a.Brand, er.brand) UNION ALL SELECT UPPER(fr.MARKETPLACE) AS Marketplace, mm.FINAL_MARKETPLACE, cast(null as string) Brand, cast(RETURN_COMPLETE_DATE as datetime) AS RETURN_DATE, UPPER(Marketing_CHANNEL) AS Marketing_channel, SUM(RETURNED_QUANTITY) AS TOTAL_RETURNED_QUANTITY, SUM(TOTAL_RETURN_AMOUNT) AS TOTAL_RETURN_AMOUNT, SUM(RETURN_TAX) AS TOTAL_RETURN_TAX, SUM(RETURN_AMOUNT_WITHOUT_TAX) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM thd-pharma-wh.MAPLEMONK.thd_pharma_wh_unicommerce_returns_fact_items fr LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from thd-pharma-wh.MAPLEMONK.marketplace_mapping ) where rw =1 ) mm ON lower(fr.marketplace) = lower(mm.marketplace) GROUP BY fr.Marketplace, mm.FINAL_MARKETPLACE, RETURN_COMPLETE_DATE, Marketing_channel;",
                    "transaction": true
                }
            ) }}
